def even_bit_set_number(n):
    # Helper function to check if a bit is even
    def is_even_bit_set(num, i):
        return (num >> i) & 1

    # Iterate through each bit position from 0 to 31 (assuming 32-bit integer)
    for i in range(32):
        if is_even_bit_set(n, i):
            # If the current bit is already even, do nothing
            continue
        else:
            # Set the current bit to even
            n |= 1 << i
    return n

