def max_sub_array_sum_repeated(arr, k):
    def max_subarray_sum(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    original_max_sum = max_subarray_sum(arr)
    n = len(arr)

    # If k == 1, the problem is already solved by max_subarray_sum
    if k == 1:
        return original_max_sum

    # Calculate the maximum sum for k > 1
    full_repetitions_sum = original_max_sum * k
    remaining_part_sum = max_subarray_sum(arr[:n//k])

    return full_repetitions_sum + remaining_part_sum * (k // (n//k) + (k % (n//k) > 0))

