def count_binary_seq(n):
    def count_sequences_with_equal_prefix_and_suffix(s):
        total_count = 0
        for i in range(2**s):
            binary_str = bin(i)[2:].zfill(s)
            prefix_sum = sum(int(bit) for bit in binary_str[:s//2])
            suffix_sum = sum(int(binary_str[s//2 + j]) for j in range(s//2))
            if prefix_sum == suffix_sum:
                total_count += 1
        return total_count

    return count_sequences_with_equal_prefix_and_suffix(2 * n)

